Index: packages/KNIRVGATEWAY/cmd/gateway/main.go
===================================================================
--- packages/KNIRVGATEWAY/cmd/gateway/main.go	
+++ packages/KNIRVGATEWAY/cmd/gateway/main.go	
@@ -1,150 +1,151 @@
 package main

 import (
 	"context"
 	"fmt"
 	"os"
 	"os/signal"
 	"syscall"
 	"time"

 	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/cloudflare"
 	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/config"
 	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/embedded"
 	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/runtime"
 	"github.com/KNIRV/KNIRV_NETWORK/KNIRVGATEWAY/internal/server"
 	"go.uber.org/zap"
 )

 func main() {
 	// Initialize logger
 	logger, err := zap.NewProduction()
 	if err != nil {
 		fmt.Fprintf(os.Stderr, "Failed to initialize logger: %v\n", err)
 		os.Exit(1)
 	}
 	defer logger.Sync()

 	// Load configuration
 	cfg, err := config.Load()
 	if err != nil {
 		logger.Fatal("Failed to load configuration", zap.Error(err))
 	}

 	logger.Info("KNIRVGATEWAY starting",
 		zap.String("mode", cfg.GatewayMode),
 		zap.Int("port", cfg.Port),
 		zap.String("chainID", cfg.ChainID),
 	)

 	// Initialize runtime and extract embedded files (oracle binary removed)
 	rt, err := runtime.NewRuntime(logger, embedded.WebGUIFS, nil)
 	if err != nil {
 		logger.Fatal("Failed to initialize runtime", zap.Error(err))
 	}

 	logger.Info("Extracting embedded services and website...")
 	if err := rt.Setup(); err != nil {
 		logger.Fatal("Failed to setup runtime", zap.Error(err))
 	}

 	// Cleanup runtime on exit
 	defer func() {
 		logger.Info("Cleaning up runtime...")
 		if err := rt.Cleanup(); err != nil {
 			logger.Error("Failed to cleanup runtime", zap.Error(err))
 		}
 	}()

 	// Oracle has moved to KNIRVSERVER — no oracle initialisation in the gateway.
 	logger.Info("Oracle is managed by KNIRVSERVER (root node only)")

 	// Initialize HTTP server with webgui static directory
 	srv, err := server.New(cfg, rt.GetWebGUIStaticPath(), logger)
 	if err != nil {
 		logger.Fatal("Failed to initialize server", zap.Error(err))
 	}

 	// Start server in a goroutine
 	go func() {
 		logger.Info("Starting HTTP server on port", zap.Int("port", cfg.Port))
 		if err := srv.Start(); err != nil {
 			logger.Fatal("Server failed", zap.Error(err))
 		}
 	}()

 	// ---- Cloudflare Tunnel (cloudflared) ----
 	//
 	// When CLOUDFLARE_API_TOKEN and CLOUDFLARE_ZONE_ID are set (propagated
 	// from root.key by KNIRVSERVER), provision a Cloudflare Tunnel for
 	// gateway.knirv.network and run cloudflared to connect from behind NAT.
 	// This follows the same conventions as proxy-penguin.

 	var tunnelRunner *cloudflare.TunnelRunner
 	tunnelCtx, tunnelCancel := context.WithCancel(context.Background())

 	if cfToken := os.Getenv("CLOUDFLARE_API_TOKEN"); cfToken != "" {
 		cfZone := os.Getenv("CLOUDFLARE_ZONE_ID")
 		if cfZone == "" {
 			logger.Warn("CLOUDFLARE_API_TOKEN set but CLOUDFLARE_ZONE_ID missing — skipping Cloudflare Tunnel")
 		} else {
 			servicePort := cfg.Port
 			if servicePort == 0 {
 				servicePort = 8081
 			}

 			tunnelRunner = cloudflare.NewTunnelRunner(cloudflare.TunnelRunnerConfig{
 				APIToken:    cfToken,
 				ZoneID:      cfZone,
+				AccountID:   os.Getenv("CLOUDFLARE_ACCOUNT_ID"),
 				TunnelName:  "knirv-gateway",
 				Hostname:    "gateway.knirv.network",
 				ServicePort: servicePort,
 			})

 			go func() {
 				logger.Info("Initialising Cloudflare Tunnel for gateway.knirv.network",
 					zap.Int("service_port", servicePort))
 				if err := tunnelRunner.Run(tunnelCtx); err != nil {
 					logger.Warn("Cloudflare Tunnel failed to start — gateway will operate without tunnel",
 						zap.Error(err))
 				}
 			}()

 			// Log the tunnel ID after a brief provisioning window.
 			go func() {
 				time.Sleep(5 * time.Second)
 				if tid := tunnelRunner.TunnelID(); tid != "" {
 					logger.Info("Cloudflare Tunnel active",
 						zap.String("tunnel_id", tid),
 						zap.String("hostname", "gateway.knirv.network"))
 				}
 			}()
 		}
 	}

 	// Wait for interrupt signal
 	quit := make(chan os.Signal, 1)
 	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
 	<-quit

 	logger.Info("Shutting down KNIRVGATEWAY")

 	// Stop Cloudflare Tunnel if running.
 	if tunnelRunner != nil {
 		logger.Info("Stopping Cloudflare Tunnel")
 		tunnelCancel()
 		tunnelRunner.Stop()
 		tunnelRunner.Wait()
 	}

 	// Graceful shutdown with timeout
 	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 	defer cancel()

 	// Stop HTTP server
 	if err := srv.Stop(ctx); err != nil {
 		logger.Error("Error stopping server", zap.Error(err))
 	}

 	logger.Info("KNIRVGATEWAY stopped")
 }

Index: packages/KNIRVGATEWAY/internal/cloudflare/api.go
===================================================================
--- packages/KNIRVGATEWAY/internal/cloudflare/api.go	
+++ packages/KNIRVGATEWAY/internal/cloudflare/api.go	
@@ -1,323 +1,326 @@
 // Package cloudflare provides a Cloudflare API client for tunnel management
 // and a cloudflared lifecycle manager.  It follows the same HTTP client and
 // tunnel lifecycle conventions demonstrated in proxy-penguin.
 package cloudflare

 import (
 	"bytes"
 	"encoding/json"
 	"fmt"
 	"io"
 	"log"
 	"net/http"
 	"strings"
 	"time"
 )

 // API is a Cloudflare v4 API client scoped to tunnel and DNS operations.
 type API struct {
 	token      string
 	accountID  string
 	zoneID     string
 	httpClient *http.Client
 	baseURL    string
 }

 // Account holds a Cloudflare account summary.
 type Account struct {
 	ID   string `json:"id"`
 	Name string `json:"name"`
 }

 // Tunnel mirrors a Cloudflare Tunnel resource.
 type Tunnel struct {
 	ID          string           `json:"id"`
 	Name        string           `json:"name"`
 	Status      string           `json:"status"`
 	AccountTag  string           `json:"account_tag"`
 	TunType     string           `json:"tun_type"`
 	Connections []TunnelConn     `json:"connections"`
 	Token       string           `json:"token,omitempty"`
 }

 // TunnelConn is one edge connection within a tunnel.
 type TunnelConn struct {
 	ColoName string `json:"colo_name"`
 	ID       string `json:"id"`
 	OriginIP string `json:"origin_ip"`
 }

 // TunnelConfig is the payload for creating / configuring a tunnel.
 type TunnelConfig struct {
 	Name      string `json:"name"`
 	ConfigSrc string `json:"config_src"`
 }

 // IngressRule maps a hostname to an upstream service URL.
 type IngressRule struct {
 	Hostname string `json:"hostname"`
 	Service  string `json:"service"`
 }

 // TunnelIngress is the full ingress configuration for a tunnel.
 type TunnelIngress struct {
 	Config struct {
 		Ingress []interface{} `json:"ingress"`
 	} `json:"config"`
 }

 // DNSRecord is a Cloudflare DNS record.
 type DNSRecord struct {
 	Type    string `json:"type"`
 	Proxied bool   `json:"proxied"`
 	Name    string `json:"name"`
 	Content string `json:"content"`
 }

 // apiResponse is the standard v4 API envelope.
 // Messages can be either strings or objects depending on the endpoint,
 // so we use interface{} and decode if needed.
 type apiResponse struct {
 	Success  bool                     `json:"success"`
 	Errors   []map[string]interface{} `json:"errors"`
 	Messages []interface{}            `json:"messages"`
 	Result   interface{}              `json:"result"`
 }

 // NewAPI creates a Cloudflare API client. accountID may be empty, in
 // which case it will be fetched from the API on first use.
-func NewAPI(token, zoneID string) *API {
+func NewAPI(token, zoneID, accountID string) *API {
 	return &API{
-		token:   strings.TrimSpace(token),
-		zoneID:  zoneID,
+		token:     strings.TrimSpace(token),
+		zoneID:    zoneID,
+		accountID: strings.TrimSpace(accountID),
 		httpClient: &http.Client{
 			Timeout: 30 * time.Second,
 		},
 		baseURL: "https://api.cloudflare.com/client/v4",
 	}
 }

 // ValidateToken checks that the provided API token is active.
 func (a *API) ValidateToken() error {
 	_, err := a.do("GET", "/user/tokens/verify", nil)
 	return err
 }

-// AccountID returns the cached account ID or fetches it from the API.
+// AccountID returns the account ID. If it was provided explicitly via
+// NewAPI, that value is used. Otherwise it falls back to fetching the
+// first account from the API (requires Account:Read permission).
 func (a *API) AccountID() (string, error) {
 	if a.accountID != "" {
 		return a.accountID, nil
 	}
 	accts, err := a.listAccounts()
 	if err != nil {
 		return "", err
 	}
 	if len(accts) == 0 {
-		return "", fmt.Errorf("no accounts associated with this token")
+		return "", fmt.Errorf("no accounts associated with this token -- provide account ID explicitly")
 	}
 	a.accountID = accts[0].ID
 	return a.accountID, nil
 }

 func (a *API) listAccounts() ([]Account, error) {
 	resp, err := a.do("GET", "/accounts", nil)
 	if err != nil {
 		return nil, err
 	}
 	data, _ := json.Marshal(resp.Result)
 	var accounts []Account
 	if err := json.Unmarshal(data, &accounts); err != nil {
 		return nil, fmt.Errorf("failed to parse accounts: %w", err)
 	}
 	return accounts, nil
 }

 // CreateTunnel creates a named tunnel and returns it.
 func (a *API) CreateTunnel(name string) (*Tunnel, error) {
 	accountID, err := a.AccountID()
 	if err != nil {
 		return nil, fmt.Errorf("account ID required: %w", err)
 	}

 	endpoint := fmt.Sprintf("/accounts/%s/cfd_tunnel", accountID)
 	resp, err := a.do("POST", endpoint, TunnelConfig{Name: name, ConfigSrc: "cloudflare"})
 	if err != nil {
 		return nil, err
 	}

 	return parseTunnel(resp.Result)
 }

 // GetTunnel retrieves a single tunnel by ID.
 func (a *API) GetTunnel(tunnelID string) (*Tunnel, error) {
 	accountID, err := a.AccountID()
 	if err != nil {
 		return nil, err
 	}
 	endpoint := fmt.Sprintf("/accounts/%s/cfd_tunnel/%s", accountID, tunnelID)
 	resp, err := a.do("GET", endpoint, nil)
 	if err != nil {
 		return nil, err
 	}
 	return parseTunnel(resp.Result)
 }

 // ListTunnels returns all tunnels for the account.
 func (a *API) ListTunnels() ([]Tunnel, error) {
 	accountID, err := a.AccountID()
 	if err != nil {
 		return nil, err
 	}
 	endpoint := fmt.Sprintf("/accounts/%s/cfd_tunnel", accountID)
 	resp, err := a.do("GET", endpoint, nil)
 	if err != nil {
 		return nil, err
 	}
 	data, _ := json.Marshal(resp.Result)
 	var tunnels []Tunnel
 	if err := json.Unmarshal(data, &tunnels); err != nil {
 		return nil, fmt.Errorf("failed to parse tunnel list: %w", err)
 	}
 	return tunnels, nil
 }

 // FindTunnelByName returns the first tunnel whose name matches.
 func (a *API) FindTunnelByName(name string) (*Tunnel, error) {
 	tunnels, err := a.ListTunnels()
 	if err != nil {
 		return nil, err
 	}
 	for i := range tunnels {
 		if tunnels[i].Name == name {
 			return &tunnels[i], nil
 		}
 	}
 	return nil, nil
 }

 // ConfigureTunnel sets the ingress rules for a tunnel.
 func (a *API) ConfigureTunnel(tunnelID string, rules []IngressRule) error {
 	accountID, err := a.AccountID()
 	if err != nil {
 		return err
 	}

 	ingress := make([]interface{}, len(rules)+1)
 	for i, r := range rules {
 		ingress[i] = r
 	}
 	catchAll := map[string]interface{}{"service": "http_status:404"}
 	ingress[len(rules)] = catchAll

 	body := TunnelIngress{}
 	body.Config.Ingress = ingress

 	endpoint := fmt.Sprintf("/accounts/%s/cfd_tunnel/%s/configurations", accountID, tunnelID)
 	_, err = a.do("PUT", endpoint, body)
 	return err
 }

 // CreateDNSRecord creates (or updates) a proxied CNAME record for the tunnel.
 func (a *API) CreateDNSRecord(hostname, tunnelID string) error {
 	if a.zoneID == "" {
 		return fmt.Errorf("zone ID not configured")
 	}

 	endpoint := fmt.Sprintf("/zones/%s/dns_records", a.zoneID)
 	record := DNSRecord{
 		Type:    "CNAME",
 		Proxied: true,
 		Name:    hostname,
 		Content: fmt.Sprintf("%s.cfargotunnel.com", tunnelID),
 	}
 	_, err := a.do("POST", endpoint, record)
 	return err
 }

 // GetTunnelToken retrieves the JWT used to authenticate a cloudflared instance.
 func (a *API) GetTunnelToken(tunnelID string) (string, error) {
 	accountID, err := a.AccountID()
 	if err != nil {
 		return "", err
 	}
 	endpoint := fmt.Sprintf("/accounts/%s/cfd_tunnel/%s/token", accountID, tunnelID)
 	resp, err := a.do("GET", endpoint, nil)
 	if err != nil {
 		return "", err
 	}
 	token, ok := resp.Result.(string)
 	if !ok {
 		return "", fmt.Errorf("unexpected token response format")
 	}
 	return token, nil
 }

 // --- internals ---

 func (a *API) do(method, endpoint string, body interface{}) (*apiResponse, error) {
 	url := a.baseURL + endpoint

 	var reqBody io.Reader
 	if body != nil {
 		data, err := json.Marshal(body)
 		if err != nil {
 			return nil, fmt.Errorf("marshal body: %w", err)
 		}
 		reqBody = bytes.NewBuffer(data)
 	}

 	req, err := http.NewRequest(method, url, reqBody)
 	if err != nil {
 		return nil, fmt.Errorf("create request: %w", err)
 	}

 	tok := strings.TrimSpace(a.token)
 	if strings.HasPrefix(strings.ToLower(tok), "bearer ") {
 		tok = tok[7:]
 	}
 	req.Header.Set("Authorization", "Bearer "+tok)
 	req.Header.Set("Content-Type", "application/json")
 	req.Header.Set("User-Agent", "knirvgateway/1.0")

 	resp, err := a.httpClient.Do(req)
 	if err != nil {
 		return nil, fmt.Errorf("request: %w", err)
 	}
 	defer resp.Body.Close()

 	respBody, _ := io.ReadAll(resp.Body)
 	log.Printf("cloudflare %s %s → %d: %s", method, endpoint, resp.StatusCode, string(respBody))

 	var r apiResponse
 	if err := json.Unmarshal(respBody, &r); err != nil {
 		return nil, fmt.Errorf("parse response: %w", err)
 	}
 	if !r.Success {
 		var msgs []string
 		for _, e := range r.Errors {
 			if code, ok := e["code"]; ok {
 				msgs = append(msgs, fmt.Sprintf("[%v] %v", code, e["message"]))
 			}
 		}
 		return nil, fmt.Errorf("API error: %s", strings.Join(msgs, ", "))
 	}
 	return &r, nil
 }

 func parseTunnel(v interface{}) (*Tunnel, error) {
 	// The API nests the tunnel under "result" inside the top-level "result".
 	if m, ok := v.(map[string]interface{}); ok {
 		if inner, ok := m["result"]; ok {
 			v = inner
 		}
 	}
 	data, err := json.Marshal(v)
 	if err != nil {
 		return nil, fmt.Errorf("marshal tunnel: %w", err)
 	}
 	var t Tunnel
 	if err := json.Unmarshal(data, &t); err != nil {
 		return nil, fmt.Errorf("unmarshal tunnel: %w", err)
 	}
 	return &t, nil
 }

Index: packages/KNIRVGATEWAY/internal/cloudflare/tunnel.go
===================================================================
--- packages/KNIRVGATEWAY/internal/cloudflare/tunnel.go	
+++ packages/KNIRVGATEWAY/internal/cloudflare/tunnel.go	
@@ -1,250 +1,251 @@
 package cloudflare

 import (
 	"bufio"
 	"context"
 	"fmt"
 	"log"
 	"os"
 	"os/exec"
 	"sync"
 )

 // TunnelRunner manages a cloudflared process that connects a named
 // Cloudflare Tunnel to a local upstream service.  It follows the same
 // lifecycle conventions demonstrated in proxy-penguin: provision the tunnel
 // via the Cloudflare API, then spawn cloudflared to maintain the connection.
 type TunnelRunner struct {
 	api          *API
 	tunnelName   string
 	tunnelID     string
 	hostname     string
 	servicePort  int

 	cmd    *exec.Cmd
 	cancel context.CancelFunc
 	mu     sync.Mutex
 	done   chan struct{}
 }

 // TunnelRunnerConfig holds the parameters for a TunnelRunner.
 type TunnelRunnerConfig struct {
 	APIToken    string // Cloudflare API token
 	ZoneID      string // Cloudflare zone ID for DNS
+	AccountID   string // Cloudflare account ID (empty = auto-discover from token)
 	TunnelName  string // tunnel name (e.g. "knirv-gateway")
 	Hostname    string // public subdomain (e.g. "gateway.knirv.network")
 	ServicePort int    // local port the gateway listens on
 }

 // NewTunnelRunner creates a TunnelRunner.  Call Run() to provision
 // and start the tunnel.
 func NewTunnelRunner(cfg TunnelRunnerConfig) *TunnelRunner {
 	return &TunnelRunner{
-		api:         NewAPI(cfg.APIToken, cfg.ZoneID),
+		api:         NewAPI(cfg.APIToken, cfg.ZoneID, cfg.AccountID),
 		tunnelName:  cfg.TunnelName,
 		tunnelID:    "", // populated by provision()
 		hostname:    cfg.Hostname,
 		servicePort: cfg.ServicePort,
 		done:        make(chan struct{}),
 	}
 }

 // Run provisions the tunnel via the Cloudflare API (creating it and its
 // DNS record if they don't exist), then spawns cloudflared.  It blocks
 // until the context is cancelled, at which point cloudflared is stopped.
 // Returns nil if the tunnel was started successfully; non-nil if
 // provisioning or cloudflared startup fails.
 func (tr *TunnelRunner) Run(ctx context.Context) error {
 	tr.mu.Lock()
 	defer tr.mu.Unlock()

 	// Step 1: validate token
 	if err := tr.api.ValidateToken(); err != nil {
 		return fmt.Errorf("cloudflare token validation failed: %w", err)
 	}
 	log.Println("[cloudflare] API token validated")

 	// Step 2: provision tunnel
 	if err := tr.provision(); err != nil {
 		return fmt.Errorf("tunnel provisioning failed: %w", err)
 	}

 	// Step 3: locate cloudflared binary
 	cfPath, err := findCloudflared()
 	if err != nil {
 		return fmt.Errorf("cloudflared not found: %w", err)
 	}

 	// Step 4: get tunnel token
 	token, err := tr.api.GetTunnelToken(tr.tunnelID)
 	if err != nil {
 		return fmt.Errorf("failed to get tunnel token: %w", err)
 	}

 	// Step 5: spawn cloudflared
 	ctx, cancel := context.WithCancel(ctx)
 	tr.cancel = cancel

 	// cloudflared tunnel run --token <token> <tunnelID>
 	cmd := exec.CommandContext(ctx, cfPath, "tunnel", "run",
 		"--token", token, tr.tunnelID)
 	cmd.Stdout = &logWriter{prefix: "cloudflared"}
 	cmd.Stderr = &logWriter{prefix: "cloudflared-err"}

 	log.Printf("[cloudflare] starting cloudflared for tunnel %s (%s)",
 		tr.tunnelName, tr.tunnelID)
 	if err := cmd.Start(); err != nil {
 		cancel()
 		return fmt.Errorf("failed to start cloudflared: %w", err)
 	}
 	tr.cmd = cmd
 	log.Printf("[cloudflare] cloudflared running (pid %d)", cmd.Process.Pid)

 	// Step 6: wait in background and signal when process exits
 	go func() {
 		defer close(tr.done)
 		if err := cmd.Wait(); err != nil {
 			log.Printf("[cloudflare] cloudflared exited: %v", err)
 		} else {
 			log.Println("[cloudflare] cloudflared stopped")
 		}
 	}()

 	return nil
 }

 // Wait blocks until the cloudflared process exits.
 func (tr *TunnelRunner) Wait() {
 	<-tr.done
 }

 // Stop gracefully stops the cloudflared process.
 func (tr *TunnelRunner) Stop() {
 	tr.mu.Lock()
 	defer tr.mu.Unlock()

 	if tr.cancel != nil {
 		tr.cancel()
 	}
 	if tr.cmd != nil && tr.cmd.Process != nil {
 		log.Printf("[cloudflare] stopping cloudflared (pid %d)", tr.cmd.Process.Pid)
 		tr.cmd.Process.Signal(os.Interrupt)
 		// Let Wait() collect the exit.
 	}
 }

 // TunnelID returns the provisioned tunnel ID (empty until Run succeeds).
 func (tr *TunnelRunner) TunnelID() string {
 	tr.mu.Lock()
 	defer tr.mu.Unlock()
 	return tr.tunnelID
 }

 // provision creates (or reuses) the Cloudflare Tunnel and its DNS record.
 func (tr *TunnelRunner) provision() error {
 	// Look for an existing tunnel with our name.
 	existing, err := tr.api.FindTunnelByName(tr.tunnelName)
 	if err != nil {
 		return fmt.Errorf("list tunnels: %w", err)
 	}

 	var tunnel *Tunnel
 	if existing != nil {
 		log.Printf("[cloudflare] reusing existing tunnel %s (%s)", tr.tunnelName, existing.ID)
 		tunnel = existing
 	} else {
 		log.Printf("[cloudflare] creating tunnel: %s", tr.tunnelName)
 		t, err := tr.api.CreateTunnel(tr.tunnelName)
 		if err != nil {
 			return fmt.Errorf("create tunnel: %w", err)
 		}
 		tunnel = t
 		log.Printf("[cloudflare] created tunnel %s (%s)", tr.tunnelName, tunnel.ID)
 	}

 	tr.tunnelID = tunnel.ID

 	// Configure ingress: hostname → local service
 	serviceURL := fmt.Sprintf("http://localhost:%d", tr.servicePort)
 	ingress := []IngressRule{
 		{Hostname: tr.hostname, Service: serviceURL},
 	}
 	if err := tr.api.ConfigureTunnel(tr.tunnelID, ingress); err != nil {
 		return fmt.Errorf("configure tunnel: %w", err)
 	}
 	log.Printf("[cloudflare] configured ingress: %s → %s", tr.hostname, serviceURL)

 	// Create DNS CNAME record (idempotent — Cloudflare returns an error
 	// if the record already exists, which we treat as a success).
 	if err := tr.api.CreateDNSRecord(tr.hostname, tr.tunnelID); err != nil {
 		// Cloudflare returns error 81053 for duplicate records — that's OK.
 		log.Printf("[cloudflare] DNS record note: %v", err)
 	} else {
 		log.Printf("[cloudflare] DNS record created: %s → %s.cfargotunnel.com",
 			tr.hostname, tr.tunnelID)
 	}

 	return nil
 }

 // findCloudflared locates the cloudflared binary on the system.
 func findCloudflared() (string, error) {
 	// Respect explicit path from environment.
 	if env := os.Getenv("CLOUDFLARED_PATH"); env != "" {
 		if _, err := os.Stat(env); err == nil {
 			return env, nil
 		}
 	}

 	// Common install locations.
 	candidates := []string{
 		"/usr/local/bin/cloudflared",
 		"/usr/bin/cloudflared",
 		"/opt/cloudflared/cloudflared",
 	}

 	// Also check PATH.
 	if p, err := exec.LookPath("cloudflared"); err == nil {
 		candidates = append([]string{p}, candidates...)
 	}

 	for _, p := range candidates {
 		if _, err := os.Stat(p); err == nil {
 			return p, nil
 		}
 	}
 	return "", fmt.Errorf("cloudflared not found — install from https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/downloads/")
 }

 // logWriter adapts a log prefix to an io.Writer for subprocess stdout/stderr.
 type logWriter struct {
 	prefix string
 }

 func (w *logWriter) Write(p []byte) (int, error) {
 	scanner := bufio.NewScanner(
 		&bytesReader{buf: p},
 	)
 	for scanner.Scan() {
 		line := scanner.Text()
 		if line != "" {
 			log.Printf("[%s] %s", w.prefix, line)
 		}
 	}
 	return len(p), nil
 }

 // bytesReader is a minimal io.Reader over a byte slice for bufio.Scanner.
 type bytesReader struct {
 	buf []byte
 	pos int
 }

 func (r *bytesReader) Read(p []byte) (int, error) {
 	if r.pos >= len(r.buf) {
 		return 0, fmt.Errorf("EOF")
 	}
 	n := copy(p, r.buf[r.pos:])
 	r.pos += n
 	return n, nil
 }

