 			StopTimeout:  time.Duration(cfg.TransactionChain.StopTimeout) * time.Second,
 			Stdout:       logging.NewSubprocessWriter("transactionchain", os.Stdout),
 			Stderr:       logging.NewSubprocessWriter("transactionchain", os.Stderr),
